  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "解释了 collective 匹配的动机，定义参与集合、rank 映射、应用身份、描述符和张量解释，并给出五类操作的输入输出及提交、完成、发布状态。库契约与应用推导的归属清楚。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "communicator 写作 C = (P, π, e)。P 是有序的 p 个 communicator ranks，π 把 rank 映射到进程和设备，e 是 communicator 身份或执行上下文。"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "AllGather 按 communicator rank 排列，若 rank s 贡献第 s 块 N 个值，则 O_r[sN+j] = I_s[j]"
        }
      ]
    },
    "legality": {
      "assessment": "partial",
      "reason": "相同 count/datatype、root 与 rank 次序等事实符合给定 NCCL 原文，也正确区分 group 选择与合法性。但局部无 payload 分支没有落实全组相同 count，可能把一个 rank 的空工作错误地转成局部零长度调用。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "固定 NCCL Collective Operations 文档要求各 rank 使用相同 count 和相同 datatype，才能组成完整操作"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "若一个 rank 没有有效 payload，空工作仍要保留共同序列，不能用本地分支删除其他参与者等待的步骤"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "只有固定 API 允许已声明的空范围时，才可把空工作表示为零长度操作"
        }
      ]
    },
    "algorithm": {
      "assessment": "partial",
      "reason": "单一 provenance 标记、来源说明和离线链接已恢复，campaign-K-SYS-005-r1 在当前候选上可关闭。完整重读仍发现非 group 异步发起、完成事件生产与 DEVICE_DONE 更新、全组失败处理没有贯通。检查脚本另建的状态表不能证明正文伪代码满足这些不变量。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "if ret is an immediate error then local_error ← ret"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "wait_state ← WAIT_FOR_DEVICE_OR_EVENT(slot.event, deadline)"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "任何本地错误或未知超时都会阻止该 seq 的输出进入下一阶段。"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "在声明的理想通信模型范围内，轮次数、每轮字节数、单向带宽和时间单位一致；独立复算 16 MiB 算例得到 615.9375 µs。区分逻辑通信量、主缓冲容量、packing 准备、提交、等待、共享资源及峰值驻留，明确模型不是设备实测。真实归约计算、HBM 事务及库内部资源仍需另行测量。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "有 2(p−1) 轮，每轮传 Nb/p 字节"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "T_ring ≈ 2(p−1)α + 2(p−1)Nb/(pβ) + H + S。"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "峰值容量可能从逐个执行时的 max_i R_i 上升到 Σ_i R_i"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "消息大小、成员与代次、动态请求决定、异步模式、拓扑及数值顺序变化均连接到具体依赖和成本，并给出缩小或放弃 group 的反转条件。空工作规则的具体合法性需按 finding 修复。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "采用 group 聚合多个层时，若关键消费者等待更久、暂存峰值超限或共享链路排队严重，应缩小 group、拆分关键路径或放弃聚合。"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "动态 batch、EOS、取消和投机接受改变本轮工作，但共同决定必须先形成。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "区分顺序错配、对端退出、链路延迟、张量解释错误和消费依赖错误，给出控制变量与预测，保留超时的不确定性。实验设计与 CPU 检查、真实多卡结果明确分开；失败闭包检查的覆盖不足另列为算法 finding。",
      "evidence": [
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "超时只说明在时间预算内未完成，不能单独区分网络慢、顺序错和对端已死。"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "下面的表是区分实验设计，不是已经在目标多卡环境完成的实测。"
        },
        {
          "path": "knowledge/system-semantics/collective-ordering.md",
          "quote": "未完成或被终止的检查保留失败或不确定结果，不能因其他 rank 得到了数值就记为全组通过。"
        }
      ]
    }
  },
  "findings": [
    {
      "id": "K-SYS-005-empty-count-contract",
      "criterion": "legality",
      "evidence": "正文同时要求“各 rank 使用相同 count 和相同 datatype”，又按 slot.has_payload(r) 分支允许“把空工作表示为零长度操作”。伪代码只在有 payload 时 reserve input and output ranges，随后所有 rank 都调用 SUBMIT。没有规定零长度必须为全组共同描述，也没有为局部空 rank 构造匹配长度的合法输入。脚本 empty = [[], [], []] 只覆盖所有 rank 同时为空。",
      "impact": "一个 rank 无工作而其他 rank 的同槽位 count 为正时，局部 count=0 会破坏 NCCL 契约；若保留正 count 却没有预留输入范围，则可能访问无效缓冲。保留槽位本身不足以保证合法。",
      "blocking": true,
      "required_revision": "区分全组零长度与局部无有效数据。全组零长度必须使用共同 count；局部空 rank 必须按操作语义提供匹配长度的合法缓冲，例如数学语义允许时填充归约单位元，否则共同拒绝或重构操作。按 Broadcast/Reduce 等角色分别定义所需输入输出范围。增加能拒绝混合零/非零 count 的检查。"
    },
    {
      "id": "K-SYS-005-ungrouped-issue-progress",
      "criterion": "algorithm",
      "evidence": "SUBMIT 后只有“if ret is an immediate error then local_error ← ret”；D.use_group 为 false 时直接设置“close_ret ← SUCCESS”。后续只在 close_ret = IN_PROGRESS 时执行 POLL_ISSUE，因此非 group SUBMIT 返回 IN_PROGRESS 的状态被丢弃，算法仍会继续提交或进入设备事件等待。",
      "impact": "正文同时讨论不使用 group 和 nonblocking communicator，却没有保证非 group 路径的发起完成；可能过早调用相关 CUDA 操作，违背本章要求的提交与设备完成分离。",
      "blocking": true,
      "required_revision": "明确 SUBMIT 的返回契约，处理非 group 每次调用的 IN_PROGRESS、错误及发起完成后才能进行的后续操作；或者明确将非 group 分支限制为已证明同步完成发起的模式。用同一执行模型覆盖 group/non-group 的成功、pending、错误与超时路径。"
    },
    {
      "id": "K-SYS-005-completion-event-production",
      "criterion": "algorithm",
      "evidence": "正文首次使用完成票据的位置是“wait_state ← WAIT_FOR_DEVICE_OR_EVENT(slot.event, deadline)”，此前没有创建或记录 slot.event，也没有说明该事件如何覆盖本 seq 的通信。等待成功后没有 DEVICE_DONE 更新，而发布处要求“require slot is DEVICE_DONE and consumer dependency satisfied”。",
      "impact": "读者无法由伪代码建立通信到完成事件的因果链；未记录或旧代次事件可能错误放行，严格按已列更新执行则没有进入 DEVICE_DONE 的步骤。另建 TRANSITIONS 表不能补足正文算法。",
      "blocking": true,
      "required_revision": "在发起确认之后明确记录覆盖相应通信的 stream/event 完成票据，绑定 communicator、seq、slot 和代次；说明等待成功的后置条件并更新 DEVICE_DONE。将 publish_set 输出映射到对应槽位，明确消费者等待和最后使用关系。检查应能拒绝未记录、旧代次或未覆盖该通信的事件。"
    },
    {
      "id": "K-SYS-005-failure-closure-gap",
      "criterion": "algorithm",
      "evidence": "正文要求“任一 rank 的本地失败、超时或提交路径未知，都必须让受影响执行组进入一致的终止、恢复或共同前缀重建”，但伪代码失败分支只有 record 后 return FAILED/ABORT；成功分支没有接收组级失败或确认提交权的步骤。脚本 failure_closure 的 timeout 分支为 pass，末尾只检查 failed 集合。手工逐分支追踪 failure_closure([(0, 'local_fail'), (0, 'abort'), (1, 'timeout')]) 和 failure_closure([(0, 'timeout'), (1, 'publish')])，两者均返回 None；这不是实际执行结果。",
      "impact": "算法没有实现其声称的失败传播不变量，也没有交代已提交通信与预留缓冲如何结算。检查器会接受成员未进入共同终态、超时后仍发布的轨迹，因此现有成功输出不能支持完整失败闭包判断。",
      "blocking": true,
      "required_revision": "给出失败与发布的明确时间边界及组级处理步骤，或明确委托给带具体输入输出契约的调用方恢复协议：停止新提交、传播失败、撤销未提交发布资格，并在确认物理最后使用结束前保留在途缓冲。不要将逻辑 abort 当作设备已排空。检查器应接收参与集合，核对所有成员的终态，拒绝未解决的 UNKNOWN 后发布和未结算在途操作，并加入上述漏检轨迹。"
    }
  ],
  "limitations": [
    "未测量 GPU、NCCL、网络、真实内存可见性、重叠、性能或知识使用效果；CPU 模型不能证明这些性质。正文对此边界的声明可以保留。",
    "理想 ring 与 group 公式不证明实际算法选择、归约计算吞吐、HBM 事务、内部暂存或共享链路争用；实际选择需要固定版本与目标环境证据。",
    "CUDA 两份原文只读取 supplied excerpts，没有据此声称完整阅读编程指南；部分选段与本章 stream/多 GPU 主题并不直接对应。",
    "当前工具未提供文件读取或 Python 执行能力，本 reviewer 未重算文件哈希、检查离线链接目标存在性或重跑脚本。documents 使用本次提供的完整材料绑定哈希。",
    "docs/knowledge-build-workflow.md 和 round-1 产物未包含在可读材料中；JSON 按本次明确提供的 schema 输出，原问题仅依据当前候选的单一标记与保留来源说明关闭。"
  ],
  "checks": [
    {
      "script": "tools/check_k_sys_005_full.py",
      "args": []
    }
  ],
  "no_checks_reason": "",
  "reading_scope": "完整阅读用户提供的以下全文，范围为提取文本的零基半开字符区间：AGENTS.md [0,567)；docs/knowledge-method.md [0,2251)；docs/knowledge-review.md [0,3016)；knowledge/system-semantics/collective-ordering.md [0,10910)；knowledge/sources/S-NCCL-GROUP.md [0,452)；knowledge/sources/S-NCCL-COLLECTIVE.md [0,493)；knowledge/sources/S-CUDA-TOPOLOGY.md [0,500)；knowledge/sources/S-CUDA-ASYNC.md [0,1610)；knowledge/algorithms/parallelism.md [0,6115)；knowledge/hardware/topology-parallelism.md [0,3562)；knowledge/system-semantics/distributed-state-transfer.md [0,3216)；knowledge/hardware/transport-and-rdma.md [0,4088)；knowledge/system-semantics/serving-recovery.md [0,3834)；knowledge/algorithms/routing-and-migration.md [0,3228)；knowledge/tools/failure-evidence.md [0,3753)；references/S-NCCL-GROUP/fulltext.txt [0,5326)；references/S-NCCL-COLLECTIVE/fulltext.txt [0,2570)。完整阅读 candidate.test_script 提供的 tools/check_k_sys_005_full.py，以及 author_notes 和 actual_preflight 的执行记录。references/S-CUDA-TOPOLOGY/fulltext.txt 仅阅读给定摘录：[16000,18254)、[68000,72000)、[344000,348000)、[436000,444000)、[448000,464000)、[468000,484000)、[496000,504000)、[516000,524000)、[528000,536000)、[572000,632000)、[752000,756000)、[976000,980000)。references/S-CUDA-ASYNC/fulltext.txt 仅阅读同组摘录，首段为 [16000,18255)，其余区间相同。两份 CUDA 原文均不列入 documents，也未声称阅读完整原文。未读取源码归档、未提供的 workflow 文件或历史产物。",
  "test_assessment": "checks 表示本轮审查的已提供 preflight 检查，不表示 reviewer 重新执行。actual_preflight 记录 returncode=0、stderr 为空、未超时，执行脚本哈希与绑定值一致；remote_bwrap 执行使用隔离网络、只读输入和 Python 3.12。作者说明未自行声称执行，与独立提供的 preflight 记录应分别理解。数值参考以逐索引归约和拼接对照闭式整数结果，p=4 的 AllReduce、AllGather、ReduceScatter 与 Broadcast 有实际断言；另覆盖 p=1、全部 rank 同时为空。shape-only 接受同 count 错槽位而身份检查拒绝，确实触及本章匹配机制；缺因子 ring 和缺 p+1 容量负对照能暴露对应模型错误。逐轮求和与闭式 ring 一致只验证给定轮次假设下的代数，不验证真实 ring 实现。状态测试检查独立手写 TRANSITIONS 表，没有执行 COLLECTIVE_STEP 的控制流，因而不能发现非 group IN_PROGRESS 丢失、缺事件记录或缺 DEVICE_DONE 更新。failure_closure 没有参与集合，忽略 timeout，不能证明共同终态；上述手工反例表明其存在漏检。尚未覆盖局部空而其他 rank 非空、正文失败传播与在途资源结算，也没有 Reduce 数值参考、浮点容差或设备执行证据。脚本成功不能消除这些当前算法缺口。"
}
